<script setup>
import { computed } from 'vue'
import { monthCells, itemsOnDate, itemColor, itemStatus, isAnomaly } from '../calendarDates.js'
const props = defineProps({ month: String, today: String, selected: String, items: { type: Array, default: () => [] }, disabled: Boolean })
defineEmits(['create', 'select', 'open'])
const cells = computed(() => monthCells(props.month).map(date => ({ date, items: itemsOnDate(props.items, date) })))
</script>
<template><div class="month" role="group" aria-label="月视图日历"><div v-for="label in ['一','二','三','四','五','六','日']" :key="label" class="weekday">周{{ label }}</div><div v-for="cell in cells" :key="cell.date" class="day" :class="{ outside: !cell.date.startsWith(month), today: cell.date === today, selected: cell.date === selected }" :data-date="cell.date"><div class="day-top"><button class="date" :aria-label="`查看 ${cell.date} 的安排`" :aria-current="cell.date === today ? 'date' : undefined" @click="$emit('select',cell.date)">{{ Number(cell.date.slice(-2)) }}</button><button class="add" :aria-label="`在 ${cell.date} 新建事件`" :disabled="disabled" @click="$emit('create',cell.date)">+</button></div><div class="dots"><button v-for="item in cell.items.slice(0,5)" :key="item.id" class="dot" :class="{ overdue: item.due_date < today, anomaly: isAnomaly(item) }" :style="{ backgroundColor: itemColor(item,today) }" :aria-label="`${cell.date}：${item.title}，${itemStatus(item,today)}${isAnomaly(item) ? '，截止日早于开始日' : ''}`" :title="`${item.title} · ${itemStatus(item,today)}`" @click="$emit('open', item)"></button><button v-if="cell.items.length > 5" class="more" :aria-label="`查看 ${cell.date} 全部 ${cell.items.length} 件事件`" @click="$emit('select',cell.date)">+{{ cell.items.length - 5 }}</button></div><button class="blank" :aria-label="`在 ${cell.date} 新建事件`" tabindex="-1" :disabled="disabled" @click="$emit('create',cell.date)"></button></div></div></template>
<style scoped>.month{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-left:1px solid var(--line);border-top:1px solid var(--line);width:100%;min-width:0}.weekday{text-align:center;background:#f3f6fc;padding:10px 0;font-size:12px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.day{min-width:0;min-height:99px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:5px;display:flex;flex-direction:column;background:#fff}.outside{background:#fafbfd;color:#929baa}.today .date{background:#3159cb;color:white;border-radius:50%}.selected{box-shadow:inset 0 0 0 2px #7293df}.day-top{display:flex;justify-content:space-between;align-items:center;gap:2px}.date,.add{padding:0;min-width:24px;width:26px;min-height:26px;height:26px;border:0;background:none}.date{font-weight:650}.add{color:#7d8fa9}.dots{display:flex;align-items:center;flex-wrap:wrap;gap:5px;padding:7px 2px;min-height:30px}.dot{width:11px;height:11px;min-height:11px;padding:0;border:1px solid #79829655;border-radius:50%;flex-shrink:0}.dot.overdue{border:2px solid #450A0A;box-shadow:0 0 0 1px #fff}.dot.anomaly{border-radius:2px;transform:rotate(45deg)}.more{min-height:22px;padding:0 3px;border:0;font-size:10px;background:none}.blank{flex:1;min-height:12px;border:0;padding:0;background:transparent;width:100%}.blank:hover{background:#edf2ff}@media(max-width:560px){.day{padding:3px;min-height:83px}.date,.add{min-width:20px;width:20px;min-height:22px;height:22px;font-size:11px}.dots{gap:4px;padding:5px 1px}.dot{width:9px;height:9px;min-height:9px}.weekday{font-size:10px}.more{font-size:9px;padding:0}}
</style>
